package com.github.auties00.daedalus.processor;

import javax.annotation.processing.RoundEnvironment;
import javax.lang.model.element.*;
import javax.lang.model.util.ElementScanner14;
import javax.lang.model.util.Elements;
import java.lang.annotation.Annotation;
import java.util.*;

/**
 * A round environment that defers the processing of some types to a later round.
 *
 * <p>A type is deferred when one of its annotations cannot be resolved yet, for example
 * because it is the companion parameters annotation of a converter that is generated by
 * the current round. javac resolves such an annotation in the next round, but only
 * reports the types generated by the previous round as the root elements of that round,
 * so a deferred type must be looked up again and reported explicitly.
 *
 * <p>This environment behaves like the environment it wraps, except that:
 * <ul>
 * <li>the deferred types, and every element they enclose, are excluded;
 * <li>the resumed types, which were deferred by a previous round and can now be
 *     processed, are included as root elements, together with every element they
 *     enclose.
 * </ul>
 */
final class DaedalusRoundEnvironment implements RoundEnvironment {
    /**
     * The round environment provided by the compiler.
     */
    private final RoundEnvironment delegate;

    /**
     * The element utility used to read annotations.
     */
    private final Elements elements;

    /**
     * The types deferred by a previous round that are processed by this round.
     */
    private final Set<TypeElement> resumedTypes;

    /**
     * The root types of this round that are deferred to a later round.
     */
    private final Set<TypeElement> deferredTypes;

    /**
     * Constructs a new round environment.
     *
     * @param delegate the round environment provided by the compiler
     * @param elements the element utility used to read annotations
     * @param resumedTypes the types deferred by a previous round that are processed by
     *        this round
     * @param deferredTypes the root types of this round that are deferred to a later round
     */
    DaedalusRoundEnvironment(RoundEnvironment delegate, Elements elements, Set<TypeElement> resumedTypes, Set<TypeElement> deferredTypes) {
        this.delegate = delegate;
        this.elements = elements;
        this.resumedTypes = resumedTypes;
        this.deferredTypes = deferredTypes;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public boolean processingOver() {
        return delegate.processingOver();
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public boolean errorRaised() {
        return delegate.errorRaised();
    }

    /**
     * {@inheritDoc}
     *
     * <p>The deferred types are excluded, while the resumed types are included.
     */
    @Override
    public Set<? extends Element> getRootElements() {
        var result = new LinkedHashSet<Element>();
        for (var element : delegate.getRootElements()) {
            if (!isDeferred(element)) {
                result.add(element);
            }
        }
        result.addAll(resumedTypes);
        return Collections.unmodifiableSet(result);
    }

    /**
     * {@inheritDoc}
     *
     * <p>The elements enclosed by a deferred type are excluded, while those enclosed by a
     * resumed type are included.
     */
    @Override
    public Set<? extends Element> getElementsAnnotatedWith(TypeElement annotation) {
        var result = new LinkedHashSet<Element>();
        for (var element : delegate.getElementsAnnotatedWith(annotation)) {
            if (!isDeferred(element)) {
                result.add(element);
            }
        }
        var annotationName = annotation.getQualifiedName().toString();
        for (var resumedType : resumedTypes) {
            collectAnnotatedElements(resumedType, annotationName, result);
        }
        return Collections.unmodifiableSet(result);
    }

    /**
     * {@inheritDoc}
     *
     * <p>The elements enclosed by a deferred type are excluded, while those enclosed by a
     * resumed type are included.
     */
    @Override
    public Set<? extends Element> getElementsAnnotatedWith(Class<? extends Annotation> annotation) {
        var result = new LinkedHashSet<Element>();
        for (var element : delegate.getElementsAnnotatedWith(annotation)) {
            if (!isDeferred(element)) {
                result.add(element);
            }
        }
        var annotationName = annotation.getCanonicalName();
        for (var resumedType : resumedTypes) {
            collectAnnotatedElements(resumedType, annotationName, result);
        }
        return Collections.unmodifiableSet(result);
    }

    /**
     * Returns whether the given element is enclosed by a deferred type.
     *
     * @param element the element
     * @return {@code true} if the outermost type enclosing the element is deferred
     */
    private boolean isDeferred(Element element) {
        if (deferredTypes.isEmpty()) {
            return false;
        }

        Element outermostType = null;
        for (var current = element; current != null; current = current.getEnclosingElement()) {
            if (current instanceof TypeElement) {
                outermostType = current;
            }
        }
        return outermostType != null && deferredTypes.contains(outermostType);
    }

    /**
     * Adds to the given set the elements enclosed by the given type, including the type
     * itself, that are annotated with the annotation with the given qualified name.
     *
     * <p>Like {@link RoundEnvironment#getElementsAnnotatedWith(TypeElement)}, the
     * annotations inherited by a class are also considered.
     *
     * @param type the type to scan
     * @param annotationName the qualified name of the annotation
     * @param result the set that receives the annotated elements
     */
    private void collectAnnotatedElements(TypeElement type, String annotationName, Set<Element> result) {
        new ElementScanner14<Void, Void>() {
            @Override
            public Void scan(Element element, Void unused) {
                if (isAnnotated(element, annotationName)) {
                    result.add(element);
                }
                return super.scan(element, unused);
            }

            @Override
            public Void visitType(TypeElement element, Void unused) {
                scan(element.getTypeParameters(), unused);
                return super.visitType(element, unused);
            }

            @Override
            public Void visitExecutable(ExecutableElement element, Void unused) {
                scan(element.getTypeParameters(), unused);
                return super.visitExecutable(element, unused);
            }
        }.scan(type);
    }

    /**
     * Returns whether the given element is annotated with the annotation with the given
     * qualified name.
     *
     * @param element the element
     * @param annotationName the qualified name of the annotation
     * @return {@code true} if the element is annotated
     */
    private boolean isAnnotated(Element element, String annotationName) {
        for (var annotation : elements.getAllAnnotationMirrors(element)) {
            if (annotation.getAnnotationType().asElement() instanceof TypeElement annotationElement
                    && annotationElement.getQualifiedName().contentEquals(annotationName)) {
                return true;
            }
        }
        return false;
    }
}
